    $cls   = $class ? " class=\"" . htmlspecialchars($class) . "\"" : '';
    $inner = $paths[$name] ?? '<!-- icon:' . htmlspecialchars($name) . ' -->';
    $sw    = $name === 'star' ? '1' : '2';
    $f     = ($name === 'star' || $name === 'play') ? 'currentColor' : 'none';

    return "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"{$size}\" height=\"{$size}\" viewBox=\"0 0 24 24\" fill=\"{$f}\" stroke=\"currentColor\" stroke-width=\"{$sw}\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"{$cls}>{$inner}</svg>";
